// ── lib/korean-calendar/authority.js ──────────────────────────────
/** Approved CR-001/002 lookup only. No runtime network, astronomy library, or persisted-result mutation. */

function authorityError(code) { const error = new RangeError(code); error.code = code; throw error; }

function selectVerifiedAuthority(flags) {
  if (flags.authorityVersion === EXPANDED_AUTHORITY_VERSION) return { version: EXPANDED_AUTHORITY_VERSION, fingerprint: EXPANDED_AUTHORITY_FINGERPRINT, years: EXPANDED_TERM_YEARS, terms: EXPANDED_NODE_TERMS, months: EXPANDED_LUNAR_MONTHS };
  if (flags.authorityVersion !== undefined && flags.authorityVersion !== VERIFIED_AUTHORITY_VERSION) authorityError('INVALID_AUTHORITY_VERSION');
  return { version: VERIFIED_AUTHORITY_VERSION, fingerprint: VERIFIED_AUTHORITY_FINGERPRINT, years: VERIFIED_TERM_YEARS, terms: VERIFIED_NODE_TERMS, months: VERIFIED_LUNAR_MONTHS };
}

function authorityMetadata(flags = {}) {
  const data = selectVerifiedAuthority(flags);
  return { version: data.version, fingerprint: data.fingerprint };
}

function verifiedLunarMonthForSolar(year, month, day, flags = {}) {
  const timestamp = Date.UTC(year, month - 1, day), date = new Date(timestamp);
  if (date.getUTCFullYear() !== year || date.getUTCMonth() + 1 !== month || date.getUTCDate() !== day) authorityError('INVALID_BIRTH_DATE');
  const serial = timestamp / 86400000;
  const entry = selectVerifiedAuthority(flags).months.find(m => m.startDay <= serial && serial < m.startDay + m.length);
  if (!entry) authorityError('CALENDAR_AUTHORITY_OUT_OF_RANGE');
  return { ...entry };
}

function verifiedLunarMonth(year, month, leap, flags = {}) {
  const entry = selectVerifiedAuthority(flags).months.find(m => m.lunarYear === year && m.monthNumber === month && m.isLeap === Boolean(leap));
  if (!entry) authorityError('CALENDAR_AUTHORITY_OUT_OF_RANGE');
  return { ...entry };
}

/**
 * Direct JPL sign brackets have finite precision. Never decide an instant within the unresolved 40 ms.
 * @returns {{previous:{year:number,index:number,utcMs:number,lowerUtcMs:number,upperUtcMs:number},next:{year:number,index:number,utcMs:number,lowerUtcMs:number,upperUtcMs:number},ipchun:{year:number,index:number,utcMs:number,lowerUtcMs:number,upperUtcMs:number}}}
 */
function verifiedNodeTermWindow(instantUtcMs, flags = {}) {
  if (!Number.isFinite(instantUtcMs)) authorityError('INVALID_TERM_INSTANT');
  const data = selectVerifiedAuthority(flags);
  const year = new Date(instantUtcMs + 9 * 3600000).getUTCFullYear();
  if (!data.years.includes(year)) authorityError('TERM_AUTHORITY_OUT_OF_RANGE');
  if (data.terms.some(t => instantUtcMs > t.lowerUtcMs && instantUtcMs < t.upperUtcMs)) authorityError('TERM_INSTANT_UNCERTAIN');
  const previous = data.terms.findLast(t => t.upperUtcMs <= instantUtcMs);
  const next = data.terms.find(t => t.lowerUtcMs >= instantUtcMs);
  const ipchun = data.terms.find(t => t.year === year && t.index === 2);
  if (!previous || !next || !ipchun) authorityError('TERM_AUTHORITY_OUT_OF_RANGE');
  return { previous: { ...previous }, next: { ...next }, ipchun: { ...ipchun } };
}


// ── lib/korean-calendar/core.js ───────────────────────────────────
/**
 * 한국 음양력 코어 — 표 위의 순수 조회·산술.
 *
 * 🔴 여기에는 천문 계산이 없다. `astronomy-engine` 을 import 하지 않는다.
 * 계산은 빌드타임에 scripts/build-korean-calendar-table.mjs 가 끝냈고, 이 파일은 그 표를 읽는다.
 * 그래서 정적 셸·앱 클라이언트 번들에 116KB 짜리 천문 라이브러리를 실을 필요가 없다.
 *
 * 🔴 표기 축을 섞지 않기 위해 **인덱스만 반환한다**(lib/ziwei-minor-limit.js 가 세운 규칙).
 * 셸은 한자('甲','寅'), 워커·앱은 한글('갑','인')을 쓴다. 문자열은 labels.js 에서만 만든다.
 */

/** 🔴 ganji.js 도 이 값을 쓴다. 두 번 선언하지 않는 이유는 클래식 번들 때문이다 —
 * scripts/build-korean-calendar-table.mjs 가 코어 소스를 한 스코프로 이어 붙이므로
 * 같은 이름을 두 모듈이 선언하면 그 자리에서 빌드가 실패한다. */
const DAY_MS = 86400000;

/** KST 민용일 일련번호(1970-01-01 = 0). 양력 날짜 하나가 정수 하나에 대응한다. */
function solarDayIndex(year, month, day) {
  return Date.UTC(year, month - 1, day) / DAY_MS;
}

/** 일련번호 → 양력 날짜. */
function solarFromDayIndex(dayIndex) {
  const d = new Date(dayIndex * DAY_MS);
  return { year: d.getUTCFullYear(), month: d.getUTCMonth() + 1, day: d.getUTCDate() };
}

// ── 음력 달 목록 (표를 한 번만 펼친다) ──────────────────────────────────────
let monthsCache = null;

function expandMonths() {
  if (monthsCache) return monthsCache;
  const months = [];
  let blockYear = TABLE_META.firstBlockYear;

  for (const row of LUNAR_BLOCKS.split(";")) {
    const [startDayText, countText, mask, leapIndexText] = row.split(",");
    const startDay = Number(startDayText);
    const count = Number(countText);
    const leapIndex = Number(leapIndexText);
    let cursor = startDay;

    for (let i = 0; i < count; i += 1) {
      const length = mask[i] === "1" ? 30 : 29;
      // 윤달을 건너뛴 순번. 블록 안 인덱스 0 이 11월이다.
      const ordinal = i - (leapIndex >= 0 && i >= leapIndex ? 1 : 0);
      months.push({
        startDay: cursor,
        length,
        isLeap: i === leapIndex,
        monthNumber: ((11 + ordinal - 1) % 12) + 1,
        // 🔴 블록의 11·12월(ordinal 0·1)은 **앞 음력해** 소속이다.
        // 여기를 i 로 쓰면 윤11월(2033)이 다음 해로 새어 그 뒤가 전부 밀린다.
        lunarYear: ordinal <= 1 ? blockYear - 1 : blockYear,
      });
      cursor += length;
    }
    blockYear += 1;
  }

  monthsCache = months;
  return months;
}

/**
 * 지원 양력 범위의 일 인덱스 경계.
 * 🔴 표는 이보다 넓게 덮는다(양력 1900-01-01 이 음력 1899년 12월이라 앞뒤로 여유가 필요하다).
 * 그러나 **회귀 증명(verify:korean-calendar-divergence)이 덮은 것은 1900~2100 뿐**이므로
 * 그 밖의 날짜는 답하지 않는다. 검증하지 않은 구간을 조용히 답하는 것이 더 위험하다.
 */
function supportedDayBounds() {
  return {
    min: solarDayIndex(TABLE_META.supportedMinYear, 1, 1),
    max: solarDayIndex(TABLE_META.supportedMaxYear, 12, 31),
  };
}

/** 양력 → 음력. 지원 범위 밖이면 null. */
function solarToLunar(year, month, day, authorityFlags = {}) {
  const target = solarDayIndex(year, month, day);
  const bounds = supportedDayBounds();
  if (target < bounds.min || target > bounds.max) return null;
  if (authorityFlags.koreanCalendarAuthorityV2 === true) {
    const entry = verifiedLunarMonthForSolar(year, month, day, authorityFlags);
    return { lunarYear: entry.lunarYear, lunarMonth: entry.monthNumber, lunarDay: target - entry.startDay + 1, isLeapMonth: entry.isLeap, monthLengthDays: entry.length };
  }
  const months = expandMonths();
  if (target < months[0].startDay) return null;
  const last = months[months.length - 1];
  if (target >= last.startDay + last.length) return null;

  let lo = 0;
  let hi = months.length - 1;
  let found = -1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (months[mid].startDay <= target) { found = mid; lo = mid + 1; } else hi = mid - 1;
  }
  const entry = months[found];
  return {
    lunarYear: entry.lunarYear,
    lunarMonth: entry.monthNumber,
    lunarDay: target - entry.startDay + 1,
    isLeapMonth: entry.isLeap,
    monthLengthDays: entry.length,
  };
}

/** 음력 → 양력. 그 해에 그 윤달이 없거나 그 달에 그 일이 없으면 null. */
function lunarToSolar(lunarYear, lunarMonth, lunarDay, isLeapMonth = false, authorityFlags = {}) {
  const entry = authorityFlags.koreanCalendarAuthorityV2 === true ? verifiedLunarMonth(lunarYear, lunarMonth, isLeapMonth, authorityFlags) : expandMonths().find(
    (m) => m.lunarYear === lunarYear && m.monthNumber === lunarMonth && m.isLeap === Boolean(isLeapMonth),
  );
  if (!entry) return null;
  if (!(lunarDay >= 1 && lunarDay <= entry.length)) return null;
  const dayIndex = entry.startDay + lunarDay - 1;
  const bounds = supportedDayBounds();
  if (dayIndex < bounds.min || dayIndex > bounds.max) return null;
  return solarFromDayIndex(dayIndex);
}

// ── 절기 ────────────────────────────────────────────────────────────────────
let termsCache = null;

function expandTerms() {
  if (termsCache) return termsCache;
  const byYear = new Map();
  for (const row of SOLAR_TERMS.split(";")) {
    const [yearText, rest] = row.split(":");
    const year = Number(yearText);
    byYear.set(
      year,
      rest.split(",").map((cell, index) => {
        const month = Number(cell.slice(0, 2));
        const day = Number(cell.slice(2, 4));
        const hour = Number(cell.slice(4, 6));
        const minute = Number(cell.slice(6, 8));
        return { index, year, month, day, hour, minute, dayIndex: solarDayIndex(year, month, day), minuteOfDay: hour * 60 + minute };
      }),
    );
  }
  termsCache = byYear;
  return termsCache;
}

/**
 * 그 해의 24절기. 인덱스 0=소한 … 23=동지. 전부 같은 양력 해 안에 닫힌다.
 * 지원 범위 밖이면 null.
 */
function solarTerms(year) {
  const found = expandTerms().get(year);
  return found ? found.map((t) => ({ ...t })) : null;
}

/** 절(節) — 월건을 여는 12개. 짝수 인덱스다. */
function nodeTerms(year) {
  const all = solarTerms(year);
  return all ? all.filter((t) => t.index % 2 === 0) : null;
}

/** 두 시각의 선후를 민용일+분으로 비교한다. 표가 분 반올림이라 초는 쓰지 않는다(오차 ≤30초). */
function isAtOrAfter(dayIndex, minuteOfDay, term) {
  if (dayIndex !== term.dayIndex) return dayIndex > term.dayIndex;
  return minuteOfDay >= term.minuteOfDay;
}

/** 그 시각이 지나온 직전 절(節). 월건의 경계다. */
function enclosingNodeTerm(year, month, day, hour, minute) {
  const dayIndex = solarDayIndex(year, month, day);
  const minuteOfDay = hour * 60 + minute;
  for (const candidateYear of [year, year - 1]) {
    const nodes = nodeTerms(candidateYear);
    if (!nodes) continue;
    for (let i = nodes.length - 1; i >= 0; i -= 1) {
      if (isAtOrAfter(dayIndex, minuteOfDay, nodes[i])) return nodes[i];
    }
  }
  return null;
}

function enclosingNodeTermAtInstant(instantUtcMs, authorityFlags = {}) {
  return verifiedNodeTermWindow(instantUtcMs, authorityFlags).previous;
}


/** 지원 양력 범위. 이 밖의 날짜는 전부 null 이다. */
function supportedRange() {
  return {
    minYear: TABLE_META.supportedMinYear,
    maxYear: TABLE_META.supportedMaxYear,
  };
}

// ── lib/korean-calendar/ganji.js ──────────────────────────────────
/**
 * 간지(干支) — 세차·월건·일진·시주. 표기 없이 **인덱스만** 낸다.
 *
 * 🔴 공식은 새로 만들지 않았다. 레포에 이미 있는 것을 그대로 옮겼다:
 *   · 일진 `floor(Date.UTC(y,m-1,d)/86400000) + 17`
 *     — js/saju-engine.js `_cdCivilDayPillar` 와
 *       app/saju/animal-destiny/engine/localSajuCalculator.ts `getDayPillar` 가 같은 값을 쓰고,
 *       scripts/test-saju-day-pillar-civil-date.mjs 가 1900~2100 스윕으로 지키고 있다.
 *     60갑자는 연속 순환이라 음력·절기와 달리 KST/CST 문제가 없다.
 *   · 야자시(23시대 → 익일 일진), 시지 `floor((hour+1)/2) % 12`, 오자둔(五鼠遁)
 *     — 같은 두 파일에서 그대로.
 *
 * 바뀐 것은 **세차·월건의 경계를 어느 나라 시간의 절기로 가르느냐** 하나뿐이다.
 * 이제 KST 절기표를 쓴다.
 */

/* 🔴 export 하는 이유는 daeun.js 가 같은 것을 필요로 해서다. 클래식 번들은 코어 소스를
   한 스코프로 이어 붙이므로 두 파일이 각자 선언하면 빌드가 그 자리에서 실패한다
   (core.js 의 DAY_MS 가 같은 이유로 export 다). */
const mod = (value, size) => ((value % size) + size) % size;

/** 서기 연도 → 세차 천간·지지 인덱스(甲=0 / 子=0). */
function sexagenaryYearIndexes(sexagenaryYear) {
  return { stemIndex: mod(sexagenaryYear - 4, 10), branchIndex: mod(sexagenaryYear - 4, 12) };
}

/**
 * 간지 네 기둥.
 *
 * @param {{year:number,month:number,day:number,hour:number,minute:number}} at  KST 벽시계
 * @param {{nightZiPolicy?:string,sajuTermAuthorityV2?:boolean,termInstantUtcMs?:number,authorityVersion?:string}} [options]
 * @returns {null|{year:{stemIndex,branchIndex}, month:{stemIndex,branchIndex},
 *                 day:{stemIndex,branchIndex}, hour:{stemIndex,branchIndex}, meta:object}}
 */
function ganji(at, options = {}) {
  const { year, month, day } = at;
  const hour = Number(at.hour) || 0;
  const minute = Number(at.minute) || 0;
  const nightZiPolicy = options.nightZiPolicy || DEFAULT_NIGHT_ZI_POLICY;

  const node = options.sajuTermAuthorityV2 === true
    ? enclosingNodeTermAtInstant(options.termInstantUtcMs, options)
    : enclosingNodeTerm(year, month, day, hour, minute);
  if (!node) return null;

  // ── 세차 — 입춘(절 인덱스 2)이 경계다.
  // 절 인덱스 0(소한)은 입춘 전이므로 그 해 세차는 아직 전년이다.
  const sexagenaryYear = node.index >= 2 ? node.year : node.year - 1;
  const yearPillar = sexagenaryYearIndexes(sexagenaryYear);

  // ── 월건 — 절 인덱스 0(소한)=丑月(1), 2(입춘)=寅月(2), … 22(대설)=子月(0).
  const monthBranchIndex = mod(node.index / 2 + 1, 12);
  // 오호둔(五虎遁): 생년간으로 寅月의 천간을 정하고 지지만큼 순행한다.
  const yinStemStart = [2, 4, 6, 8, 0][yearPillar.stemIndex % 5];
  const monthPillar = {
    stemIndex: mod(yinStemStart + mod(monthBranchIndex - 2, 12), 10),
    branchIndex: monthBranchIndex,
  };

  // ── 일진 — 야자시 정책이 적용되는 **유일한** 축이다.
  let civil = { year, month, day };
  const nightZiApplied = nightZiPolicy === NIGHT_ZI_POLICY.SHIFT_DAY && hour >= 23;
  if (nightZiApplied) {
    const shifted = new Date(Date.UTC(year, month - 1, day) + DAY_MS);
    civil = { year: shifted.getUTCFullYear(), month: shifted.getUTCMonth() + 1, day: shifted.getUTCDate() };
  }
  const serial = solarDayIndex(civil.year, civil.month, civil.day) + 17;
  const dayPillar = { stemIndex: mod(serial, 10), branchIndex: mod(serial, 12) };

  // ── 시주 — 시지는 자시가 23:00~00:59 로 자정을 감싸므로 날짜와 무관하다.
  const hourBranchIndex = Math.floor((hour + 1) / 2) % 12;
  const ziStemStart = [0, 2, 4, 6, 8][dayPillar.stemIndex % 5];
  const hourPillar = {
    stemIndex: mod(ziStemStart + hourBranchIndex, 10),
    branchIndex: hourBranchIndex,
  };

  return {
    year: yearPillar,
    month: monthPillar,
    day: dayPillar,
    hour: hourPillar,
    meta: {
      sexagenaryYear,
      dayPillarCivilDate: civil,
      nightZiApplied,
      nodeTermIndex: node.index,
      nodeTermYear: node.year,
    },
  };
}

// ── lib/korean-calendar/daeun.js ──────────────────────────────────
/**
 * 대운(大運) — 순역·기운 나이·10주기 간지.
 *
 * 🔴 **알고리즘을 새로 만들지 않았다. `lunar-javascript` 의 `EightChar.getYun(gender)` 관례를
 * 그대로 재현한 것이다.** 이 축은 유파마다 절사 관례가 갈려서, "더 정확한 계산"으로 바꾸면
 * 그 순간 기존 사용자의 대운 나이가 전부 움직인다. 그래서 옮기는 것은 **달력 하나뿐**이다 —
 * 節(절)을 중국 표준시(UTC+8)로 잡던 것을 한국 표준시로 잡는다.
 *
 * 재현한 관례(lunar-javascript 1.7.7 `getYun(gender)` 의 sect 1, 기본값):
 *
 *   순역   양년(세차 천간 짝수 인덱스) 남자 · 음년 여자 → 순행, 나머지는 역행
 *   구간   순행이면 [생시 → 다음 節], 역행이면 [직전 節 → 생시]
 *   거리   시진(2시간) 단위로 센다. 23시대는 시지 0 이 아니라 **11** 로 본다(그 관례 그대로다)
 *            hourDiff = 끝 시지 - 시작 시지
 *            dayDiff  = 끝 민용일 - 시작 민용일
 *            hourDiff < 0 이면 hourDiff += 12, dayDiff -= 1
 *            monthDiff = floor(hourDiff * 10 / 30)
 *            month = dayDiff * 4 + monthDiff          ← 3일 = 1년(=12개월)이므로 1일 = 4개월
 *            day   = hourDiff * 10 - monthDiff * 30   ← 1시진 = 10일
 *            year  = floor(month / 12);  month -= year * 12
 *   시작   생년월일 + year년 + month월 + day일 (월말 보정은 lunar-javascript 와 같다)
 *   나이   **세는 나이 정수**다. 0번 칸은 태어난 해부터 대운 시작 전년까지의 "미입운" 구간이고
 *          1번 칸부터 10년씩이다. 이 축을 0부터의 소수 나이와 섞지 말 것.
 *   간지   월주에서 순행이면 +index, 역행이면 -index
 *
 * 🔴 `daeunFromFrame` 은 **표를 안 읽는다.** 절기를 인자로 받는다 —
 * 그래야 가드가 같은 함수에 중국 표준시 절기를 먹여 lunar-javascript 와 **잔차 0** 을 증명할 수 있다.
 * 그 증명이 "이 포팅은 관례 재현이고 달라지는 것은 달력뿐" 의 유일한 근거다
 * (scripts/verify-daeun-korean-calendar.mjs 검사 ①).
 */

/**
 * 대운이 쓰는 시지 인덱스. 🔴 23시대를 0 이 아니라 11 로 본다 —
 * lunar-javascript 의 `(end.getHour() === 23) ? 11 : getTimeZhiIndex(...)` 를 그대로 옮긴 것이다.
 * 이 한 줄이 23시대 출생의 기운 나이를 정한다.
 */
function yunBranchIndex(hour) {
  const h = Number(hour) || 0;
  if (h === 23) return 11;
  return Math.floor((h + 1) / 2) % 12;
}

const DAYS_IN_MONTH = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
const isLeapYear = (year) => (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
const daysOfMonth = (year, month) => (month === 2 && isLeapYear(year) ? 29 : DAYS_IN_MONTH[month - 1]);

/**
 * 생일 + n년 + m월 + d일. 🔴 lunar-javascript 의 `nextYear → nextMonth → next` 순서와
 * 월말 보정을 그대로 따른다(2/29 → 2/28, 말일 넘침은 그 달 말일로 자른다).
 * 순서를 바꾸면 말일 근처에서 하루가 달라진다.
 */
function advance(birth, years, months, days) {
  let year = birth.year + years;
  let month = birth.month;
  let day = birth.day;
  if (month === 2 && day > 28 && !isLeapYear(year)) day = 28;

  const total = (year * 12 + (month - 1)) + months;
  year = Math.floor(total / 12);
  month = (total % 12) + 1;
  const maxDay = daysOfMonth(year, month);
  if (day > maxDay) day = maxDay;

  return solarFromDayIndex(solarDayIndex(year, month, day) + days);
}

/** 그 시각을 지난 첫 절(節). 표 밖이면 null. */
function nextNodeTerm(year, month, day, hour, minute) {
  const dayIndex = solarDayIndex(year, month, day);
  const minuteOfDay = hour * 60 + minute;
  for (const candidateYear of [year, year + 1]) {
    const nodes = nodeTerms(candidateYear);
    if (!nodes) continue;
    for (const node of nodes) {
      if (node.dayIndex > dayIndex || (node.dayIndex === dayIndex && node.minuteOfDay > minuteOfDay)) {
        return node;
      }
    }
  }
  return null;
}

/** 그 시각까지 지나온 마지막 절(節). 표 밖이면 null. */
function prevNodeTerm(year, month, day, hour, minute) {
  const dayIndex = solarDayIndex(year, month, day);
  const minuteOfDay = hour * 60 + minute;
  for (const candidateYear of [year, year - 1]) {
    const nodes = nodeTerms(candidateYear);
    if (!nodes) continue;
    for (let i = nodes.length - 1; i >= 0; i -= 1) {
      const node = nodes[i];
      if (node.dayIndex < dayIndex || (node.dayIndex === dayIndex && node.minuteOfDay <= minuteOfDay)) {
        return node;
      }
    }
  }
  return null;
}

// Identifies the existing sect-1 conversion and counting-age convention.
// Additive metadata: saved charts without this field remain readable as legacy snapshots.
const DAEUN_POLICY_VERSION = "daeun-kst-sect1-counting-age-v1";
const secondsOf = (moment) => Number(moment.second) || 0;

/**
 * 순수 계산. 표를 안 읽고 넘겨받은 절기만 쓴다.
 *
 * @param {object} input
 * @param {{year,month,day,hour,minute,second?}} input.birth        생시(벽시계)
 * @param {number} input.yearStemIndex                              세차 천간 인덱스(甲=0)
 * @param {{stemIndex:number,branchIndex:number}} input.monthPillar 월주
 * @param {{year,month,day,hour,minute,second?}} input.prevNode     직전 節
 * @param {{year,month,day,hour,minute,second?}} input.nextNode     다음 節
 * @param {"M"|"F"} input.gender
 * @param {number} [input.birthCivilYear=birth.year]                 양력 민용 출생연도(세는 나이 전용)
 * @param {number} [input.count=10]                                 대운 칸 수(0번 미입운 포함)
 */
function daeunFromFrame({ birth, yearStemIndex, monthPillar, prevNode, nextNode, gender, count = 10, birthCivilYear = birth.year }) {
  if (!Number.isInteger(birthCivilYear)) return null;
  const male = String(gender || "").toUpperCase() === "M";
  const yangYear = yearStemIndex % 2 === 0;
  const forward = (yangYear && male) || (!yangYear && !male);

  const from = forward ? birth : prevNode;
  const to = forward ? nextNode : birth;
  if (!from || !to) return null;

  let hourDiff = yunBranchIndex(to.hour) - yunBranchIndex(from.hour);
  let dayDiff = solarDayIndex(to.year, to.month, to.day) - solarDayIndex(from.year, from.month, from.day);
  if (hourDiff < 0) {
    hourDiff += 12;
    dayDiff -= 1;
  }
  const monthDiff = Math.floor((hourDiff * 10) / 30);
  let months = dayDiff * 4 + monthDiff;
  const days = hourDiff * 10 - monthDiff * 30;
  const years = Math.floor(months / 12);
  months -= years * 12;

  const startSolar = advance(birth, years, months, days);
  if (!startSolar) return null;

  const step = forward ? 1 : -1;
  const monthCycleIndex = mod(monthPillar.stemIndex - monthPillar.branchIndex, 12) * 5 + monthPillar.stemIndex;
  const cycles = [];
  for (let index = 0; index < count; index += 1) {
    if (index < 1) {
      // 🔴 0번 칸은 대운이 아니라 **미입운 구간**이다. 간지가 없다(lunar-javascript 도 '' 를 낸다).
      cycles.push({
        index: 0,
        stemIndex: null,
        branchIndex: null,
        startYear: birthCivilYear,
        endYear: startSolar.year - 1,
        startAge: 1,
        endAge: startSolar.year - birthCivilYear,
      });
      continue;
    }
    const startYear = startSolar.year + (index - 1) * 10;
    // KST conversion may cross New Year for an overseas birth. The term clock
    // measures the interval; counting age still refers to the civil birth year.
    const startAge = startYear - birthCivilYear + 1;
    const cycleIndex = mod(monthCycleIndex + step * index, 60);
    cycles.push({
      index,
      stemIndex: cycleIndex % 10,
      branchIndex: cycleIndex % 12,
      startYear,
      endYear: startYear + 9,
      startAge,
      endAge: startAge + 9,
    });
  }

  return {
    forward,
    start: { years, months, days },
    startSolar,
    cycles,
    meta: {
      policyVersion: DAEUN_POLICY_VERSION,
      ageBasis: "korean-counting-age",
      birthCivilYear,
      calendarFrame: "KST",
      referenceNode: forward ? nextNode : prevNode,
      referenceTerm: forward ? "next-node" : "prev-node",
      hourDiff,
      dayDiff,
      // 초는 관례상 안 쓴다(시진 단위로 자른다). 넘어온 값은 참고로만 남긴다.
      boundarySeconds: { from: secondsOf(from), to: secondsOf(to) },
    },
  };
}

/**
 * 한국 표준시 절기표로 대운을 낸다.
 *
 * @param {{year,month,day,hour,minute}} at  KST 벽시계
 * @param {{gender:"M"|"F", count?:number, nightZiPolicy?:string, birthCivilYear?:number}} options
 */
function daeun(at, options = {}) {
  const gz = ganji(at, options);
  if (!gz) return null;

  const hour = Number(at.hour) || 0;
  const minute = Number(at.minute) || 0;
  const birth = { year: at.year, month: at.month, day: at.day, hour, minute };

  const prev = prevNodeTerm(at.year, at.month, at.day, hour, minute);
  const next = nextNodeTerm(at.year, at.month, at.day, hour, minute);
  if (!prev || !next) return null;

  return daeunFromFrame({
    birth,
    yearStemIndex: gz.year.stemIndex,
    monthPillar: gz.month,
    prevNode: prev,
    nextNode: next,
    gender: options.gender,
    count: options.count,
    birthCivilYear: options.birthCivilYear,
  });
}

const __daeunInternals = { yunBranchIndex, advance, prevNodeTerm, nextNodeTerm, DAY_MS };

